demos = [
 ([(0,0),(0,11),(1,4),(2,7),(5,14)], [(3,1),(3,13),(4,10),(5,6)], (7,17)),
 ([(0,12),(4,3),(4,7)], [(1,1),(1,4),(2,9)], (7,14)),
 ([(1,13),(3,8),(4,5),(5,0)], [(0,6),(2,2),(5,11)], (7,15)),
 ([(1,5),(2,0)], [(4,2)], (7,7)),
 ([(4,3)], [(1,0)], (7,5)),
]
blocks=[]
for i,(ch,st,(H,W)) in enumerate(demos):
    for p in ch: blocks.append((i,tuple(p),1,H,W))
    for p in st: blocks.append((i,tuple(p),0,H,W))

def feats(i,p,H,W):
    r,c=p; oth=[q for (j,q,l,_,_) in blocks if j==i and q!=p]
    f={}
    f['top']=int(r==0); f['bottom']=int(r+2>=H); f['left']=int(c==0); f['right']=int(c+2>=W)
    for dr in range(-4,5):
        for dc in range(-4,5):
            if dr==dc==0: continue
            f[f'n{dr},{dc}']=int((r+dr,c+dc) in oth)
    f['rowov']=int(any(not(q[0]+2<=r or r+2<=q[0]) for q in oth))
    f['colov']=int(any(not(q[1]+2<=c or c+2<=q[1]) for q in oth))
    f['any']=int(bool(oth))
    return f
names=list(feats(0,(0,0),7,17))
import numpy as np
X=np.array([[feats(*b)[:0] or [feats(b[0],b[1],b[3],b[4])[k] for k in names] for b in blocks]]).reshape(len(blocks),len(names))
y=np.array([b[2] for b in blocks])
from itertools import combinations, product
lits=[(k,True) for k in names]+[(k,False) for k in names]
Xb=X.astype(bool)
sols=[]
for r_ in range(1,4):
    for combo in combinations(range(len(lits)),r_):
        pred=np.zeros(len(y),bool)
        for ci in combo:
            k,pos=lits[ci]; v=Xb[:,names.index(k)]
            pred |= (v if pos else ~v)
        if (pred==y.astype(bool)).all():
            sols.append([('+' if lits[c][1] else '-')+lits[c][0] for c in combo])
print(len(sols))
